coachView.loadJsFunction:
var amend = this.context.options.requestAmend.get("value") || "amend";
var recreate = this.context.options.requestRecreate.get("value") || "recreate";

if (this.context.options.requestType.get("value") == recreate || this.context.options.requestType.get("value") == amend) {

	this.ui.get("Display_text1").setVisible(true, true);
	this.ui.get("regenerateRemLetter").setVisible(true, true);
}else{
	this.ui.get("Display_text1").setVisible(false, true);
	this.ui.get("regenerateRemLetter").setVisible(false, true);
}

inlineScript.scriptBlock:
this.ShowRegeneratedRemittanceLetter = function () {
	//default
	this.ui.get("generateRemittanceLetter")?.setVisible(false, true);
	this.ui.get("regenerateRemittanceLetter")?.setVisible(false, true);

	var create = this.context.options.requestCreate?.get("value") || "create";
	var activityName = this.context.options.activityName?.get("value") == "ACT04";
	var amend = this.context.options.requestAmend?.get("value") || "amend";
	var recreate = this.context.options.requestRecreate?.get("value") || "recreate";
	var requestType = this.context.options.requestType?.get("value");
	 
	if (this.context.binding.get("value").get("regenerateRemLetter") == false ) {
		this.ui.get("Horizontal_Layout4")?.setVisible(false, true);
		this.ui.get("generateRemittanceLetter")?.setVisible(false, true);
		this.ui.get("regenerateRemittanceLetter")?.setVisible(false, true);
	} else {
		this.ui.get("Horizontal_Layout4")?.setVisible(true, true);
		this.ui.get("regenerateRemLetterOption")?.setVisible(true, true);
		this.setBtnsVis(requestType, recreate, amend, activityName);
	}
	
	if (requestType == create && activityName) {
		this.ui.get("generateRemittanceLetter")?.setVisible(true, true);
		this.ui.get("regenerateRemittanceLetter")?.setVisible(false, true);
		
	}
};

this.setLetterTitleVis = function () {
	this.ui.get("Text1").setVisible(false, true);
	if (this.context.binding.get("value").get("regenerateRemLetterOption").get("name") == "003") {
		this.ui.get("Text1").setVisible(true, true);
	}
};

this.setBtnsVis = function (requestType, recreate, amend, activityName) {
	if (requestType == recreate || requestType == amend) {
		if (activityName) {
			this.ui.get("generateRemittanceLetter").setVisible(true, true);
			this.ui.get("regenerateRemittanceLetter").setVisible(true, true);
		}
	}
};
